-- Populate GAIA Knowledge Base with fiscal Q&A from 730/2025 documents

-- Spese Universitarie Non Statali
INSERT INTO gaia_knowledge_base (category, question, answer_simple, answer_technical, keywords, sources, priority, active) VALUES
('spese_universitarie', 'Posso detrarre le spese per l''università privata?', 'Sì, puoi detrarre le spese per università non statali entro limiti stabiliti per facoltà e area geografica. Devi indicare il codice 13 nei righi E8-E10 del 730.', 'Le spese per università non statali sono detraibili dall''IRPEF entro limiti annuali per facoltà e area territoriale (DM 1924/2024). Detraibili anche dottorati, specializzazioni, master. Aggiungere tassa regionale diritto allo studio. Codice 13, righi E8-E10 (730) o RP8-RP13 (REDDITI PF).', ARRAY['università', 'detrazione', 'spese universitarie', 'università privata', 'codice 13'], '[{"type":"decreto","ref":"DM 1924 del 20/12/2024","source":"GU Serie Generale n.19 del 24/01/2025"}]', 1, true),

('spese_universitarie', 'Quanto posso detrarre per l''università privata?', 'L''importo massimo detraibile dipende dalla tua facoltà e dalla regione dell''università. Consulta il decreto ministeriale per i limiti precisi.', 'Gli importi massimi detraibili per anno 2024 sono stabiliti dal DM 1924/2024 art.1, differenziati per area disciplinare e territoriale. Include anche tassa regionale per diritto allo studio.', ARRAY['limite detrazione', 'importo massimo', 'università privata'], '[{"type":"decreto","ref":"DM 1924/2024 art.1"}]', 2, true),

-- Addizionali Comunali (esempi da tabella)
('addizionali_comunali', 'Come funzionano le addizionali comunali?', 'Ogni comune applica un''aliquota diversa sul tuo reddito. Alcune città hanno anche soglie di esenzione sotto le quali non paghi nulla.', 'L''addizionale comunale varia per comune con aliquote diverse. Alcuni comuni prevedono scaglioni progressivi o soglie di esenzione. Si calcola su saldo 2024 e acconto 2025 (modelli 730/2025 e RPF/2025).', ARRAY['addizionale comunale', 'aliquota comunale', 'esenzione'], '[{"type":"tabella","ref":"Tabella Addizionali Comunali 2025"}]', 1, true),

('addizionali_comunali', 'Il mio comune ha un''esenzione per l''addizionale?', 'Molti comuni prevedono esenzioni sotto una certa soglia di reddito (es. 12.000€, 15.000€). Controlla la tabella del tuo comune specifico.', 'Le soglie di esenzione sono indicate nella colonna "Esenzione" della tabella addizionali comunali. Esempi: Abano Terme 12.000€, Abbadia Lariana 15.000€, Acerno 7.500€.', ARRAY['esenzione', 'soglia esenzione', 'reddito minimo'], '[{"type":"tabella","ref":"Tabella Addizionali Comunali col. Esenzione"}]', 2, true),

-- Detrazioni Generali 730
('detrazioni_lavoro', 'Quali sono le detrazioni per lavoro dipendente?', 'Hai diritto a una detrazione base di €1.880 che diminuisce all''aumentare del reddito. Se lavori tutto l''anno e guadagni oltre €28.000, la detrazione si riduce progressivamente.', 'Detrazione lavoro dipendente: base €1.880 per redditi fino €15.000, decrescente fino ad azzerarsi oltre €50.000. Proporzionale ai giorni lavorati. Applicata automaticamente in CU e riportata in Quadro C del 730.', ARRAY['detrazione lavoro', 'lavoro dipendente', '€1880', 'giorni lavorati'], '[{"type":"istruzioni","ref":"730/2025 Quadro C"}]', 1, true),

('detrazioni_carichi', 'Posso detrarre per figli a carico?', 'Sì, ma dal 2022 per figli sotto 21 anni c''è l''Assegno Unico Universale. Per figli over 21 rimangono le detrazioni tradizionali del 730.', 'Dal 01/03/2022 l''Assegno Unico Universale sostituisce detrazioni per figli under 21. Per over 21: detrazione €950 per figlio, con maggiorazioni per disabilità. Ripartizione 50% tra genitori o 100% al genitore con reddito più alto.', ARRAY['figli a carico', 'assegno unico', 'detrazioni familiari'], '[{"type":"istruzioni","ref":"730/2025 sezione detrazioni carichi famiglia"}]', 1, true),

-- Spese Detraibili Comuni
('spese_sanitarie', 'Quali spese sanitarie posso detrarre?', 'Puoi detrarre il 19% delle spese mediche che superano €129,11. Include visite, farmaci, esami, ticket, protesi e occhiali.', 'Detrazione 19% su spese sanitarie eccedenti franchigia €129,11. Include: spese mediche generiche, farmaci con ricetta, dispositivi medici, ticket SSN, protesi, occhiali. Necessari scontrini parlanti o fatture con codice fiscale paziente.', ARRAY['spese sanitarie', 'detrazione 19%', 'farmaci', 'visite mediche', '€129,11'], '[{"type":"istruzioni","ref":"730/2025 Quadro E righi E1-E5"}]', 1, true),

('spese_ristrutturazione', 'Come funziona il bonus ristrutturazione?', 'Puoi detrarre il 50% delle spese di ristrutturazione (max €96.000) in 10 anni. Devi pagare con bonifico parlante e indicarlo nel 730.', 'Detrazione 50% su spese ristrutturazione edilizia (max €96.000 per unità immobiliare) ripartita in 10 quote annuali. Requisiti: bonifico parlante con causale, ritenuta d''acconto, comunicazione ENEA se interventi risparmio energetico. Quadro E codice specifico.', ARRAY['ristrutturazione', 'bonus casa', '50%', 'bonifico parlante'], '[{"type":"istruzioni","ref":"730/2025 Quadro E ristrutturazioni"}]', 2, true),

-- Procedura 730
('procedura_730', 'Entro quando devo presentare il 730?', 'Il 730 precompilato va presentato entro il 30 settembre 2025. Se hai un CAF o commercialista, loro hanno scadenze proprie per inviarti la dichiarazione.', 'Scadenza presentazione 730/2025: 30 settembre 2025 per invio diretto tramite sito Agenzia Entrate. CAF/professionisti abilitati hanno termini diversi per consegna al contribuente e invio telematico.', ARRAY['scadenza 730', '30 settembre', 'presentazione'], '[{"type":"istruzioni","ref":"730/2025 Istruzioni generali"}]', 1, true),

('procedura_730', 'Cosa è la CU e dove la trovo?', 'La Certificazione Unica (CU) è il documento che il tuo datore di lavoro ti dà entro marzo. Contiene tutti i dati dei tuoi redditi e ritenute dell''anno precedente.', 'La CU (Certificazione Unica) è rilasciata dal sostituto d''imposta entro 16 marzo. Contiene: redditi di lavoro dipendente/assimilati, ritenute IRPEF, addizionali, detrazioni applicate. È la base per compilazione automatica 730 precompilato.', ARRAY['certificazione unica', 'CU', 'datore lavoro'], '[{"type":"istruzioni","ref":"730/2025 - CU"}]', 1, true);